const toggle=document.querySelector('.nav-toggle');const nav=document.querySelector('#navigation');function closeNav(){toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation');nav.classList.remove('open')}toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeNav));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav()});window.matchMedia('(min-width:901px)').addEventListener('change',closeNav);
const photoDialog=document.querySelector('#photo-dialog');document.querySelectorAll('[data-image]').forEach(button=>button.addEventListener('click',()=>{const image=document.querySelector('#large-photo');image.src=button.dataset.image;image.alt=button.dataset.caption;document.querySelector('#photo-caption').textContent=button.dataset.caption;photoDialog.showModal();document.body.classList.add('modal-open')}));document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})});
const sections=document.querySelectorAll('main section[id]');if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){nav.querySelectorAll('a').forEach(a=>{if(a.hash==='#'+entry.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}})},{rootMargin:'-15% 0px -65% 0px'});sections.forEach(s=>observer.observe(s))}
